+ rng:=rand.New(rand.NewSource(87))
+ random:=make([]byte,128<<10);rng.Read(random)
+ items=append(items,sample{"heldout_random",[][]byte{random}})
+ base:=make([]byte,512);rng.Read(base)
+ var changing []byte
+ for n:=0;n<384;n++ {copyPart:=bytes.Clone(base);copyPart[rng.Intn(len(base))]=byte(n);copyPart[rng.Intn(len(base))]=byte(n>>2);changing=append(changing,copyPart...)}
+ items=append(items,sample{"heldout_near_repeat",[][]byte{changing}})
