+ items=append(items,sample{"heldout_topics",[][]byte{topics.Bytes()}})
+ var short [][]byte
+ for n:=0;n<128;n++ {short=append(short,[]byte(fmt.Sprintf("{\"seq\":%d,\"route\":\"/dat/thread%d\",\"nonce\":\"%016x\",\"body\":\"%s\"}",n,n%11,rng.Uint64(),phrases[n%len(phrases)])))}
